data.script:
//@version=5
indicator("Tick Delta VWAP Scalp Strategy", overlay=true, timeframe="1")

// === Tick Delta ===
delta = volume * (close - open)

// === Delta EMA ===
deltaFast = ta.ema(delta, 3)
deltaSlow = ta.ema(delta, 8)

// === VWAP ===
vwap = ta.vwap(close)

// === Giriş Şartları ===
longCond  = deltaFast > deltaSlow and close > vwap
shortCond = deltaFast < deltaSlow and close < vwap

// === Çıkış Şartları ===
exitLong = ta.crossunder(deltaFast, deltaSlow)
exitShort = ta.crossover(deltaFast, deltaSlow)

// === Görsel ===
plot(vwap, color=color.new(color.yellow, 0), title="VWAP")
plotshape(longCond, title="Long Entry", color=color.new(color.lime, 0), style=shape.triangleup, location=location.belowbar, size=size.tiny)
plotshape(shortCond, title="Short Entry", color=color.new(color.red, 0), style=shape.triangledown, location=location.abovebar, size=size.tiny)

// === Uyarı ===
alertcondition(longCond, title="Long Entry", message="✅ Delta + VWAP scalp LONG")
alertcondition(shortCond, title="Short Entry", message="🚨 Delta + VWAP scalp SHORT")

bgcolor(longCond ? color.new(color.lime, 90) : shortCond ? color.new(color.red, 90) : na)
